/* axes.c */

/* internal.h */
/* Helpers the parts share. Never part of the public API. */
#ifndef RANT_MATH_INTERNAL_H
#define RANT_MATH_INTERNAL_H

#include <math.h>
#include <stdlib.h>
#include <string.h>


#define I_MATH_PI 3.14159265358979323846
/* Below this a length counts as zero when it decides a degenerate case. */
#define I_MATH_TINY 1e-12

static inline double i_math_sqr(double x){ return x * x; }
static inline double i_math_clamp(double x, double lo, double hi){
    return x < lo ? lo : (x > hi ? hi : x);
}
static inline double i_math_min(double a, double b){ return a < b ? a : b; }
static inline double i_math_max(double a, double b){ return a > b ? a : b; }
/* Neither NaN nor infinite, without the classify macros some C libraries warn in. */
static inline int i_math_finite(double x){ return x - x == 0.0; }
static inline int i_math_finite3(RantDouble3 p){ return i_math_finite(p.x) && i_math_finite(p.y) && i_math_finite(p.z); }

/* Intersection over union from the shared measure and each one's own, 0 for nothing shared. */
static inline double i_math_iou(double both, double a, double b){
    double either = a + b - both;
    return both > 0.0 && either > 0.0 ? i_math_min(1.0, both / either) : 0.0;
}

/* A 2D point on z = 0, and a 3D point seen from above, for 2D work a 3D answer covers. */
static inline RantDouble3 i_math_lift(RantDouble2 v){ return rant_double3(v.x, v.y, 0.0); }
static inline RantDouble2 i_math_flat(RantDouble3 v){ return rant_double2(v.x, v.y); }

/* The points p1 + s d1 and p2 + t d2 nearest each other, s in [0, hi1] and t in [0, hi2],
 * hi HUGE_VAL for a ray. */
void i_math_closest_lines(RantDouble3 p1, RantDouble3 d1, double hi1,
                          RantDouble3 p2, RantDouble3 d2, double hi2, double *s, double *t);

/* The rule of a call that writes a list: *count holds the room and gets the need. */
static inline RantMathResult i_math_room(uint32_t *count, uint32_t need, const void *out){
    uint32_t room = *count;
    *count = need;
    return need > room || (need && !out) ? RANT_MATH_ERR_SPACE : RANT_MATH_OK;
}

/* A box lo to hi in dim axes, 2 or 3, shared by the 2D and 3D boxes. closest returns the
 * signed distance, raycast 1 with the distance along a unit direction. */
double i_math_box_closest(int dim, const double *lo, const double *hi, const double *p, double *point, double *normal);
int    i_math_box_raycast(int dim, const double *lo, const double *hi, const double *o, const double *d,
                          double *t, double *normal);
void   i_math_box_grow(int dim, double *lo, double *hi, double margin);

/* The nearest point of the edges pts[i] to pts[i + 1], closed back to the first, and its distance.
 * normal faces where it grows, given out 1 when the right of each edge is outside and q's inside. */
double i_math_edges_closest(const RantDouble2 *pts, uint32_t n, int closed, RantDouble2 q, double out, int inside,
                            RantDouble2 *point, RantDouble2 *normal);

/* The point of triangle a b c nearest p, as weights on its corners. */
void i_math_triangle_closest(RantDouble3 a, RantDouble3 b, RantDouble3 c, RantDouble3 p, double w[3]);

/* The unit direction from a to b, +z when they meet. And a unit vector square to a unit axis,
 * level where it can be, so a 2D shape lifted to z = 0 keeps its answers in the plane. */
RantDouble3 i_math_axis(RantDouble3 a, RantDouble3 b);
RantDouble3 i_math_side(RantDouble3 axis);

/* A camera checked once for work on many points, in OpenCV's optical frame: x right, y down,
 * z ahead. Out to where each bound, a polynomial in the radius, first reaches 0, its lens is one to one. */
typedef struct {
    const RantCameraIntrinsics *c;
    int fisheye;
    double k[8];
    double bound[3][14];
    int degree[3], bounds;
    double fold;     /* the radius where the first bound reaches 0, below 0 until found */
} i_MathLens;

/* many finds the fold now, which then answers each point at once. */
RantMathResult i_math_lens(const RantCameraIntrinsics *c, int many, i_MathLens *lens);
RantMathResult i_math_lens_project(i_MathLens *lens, RantDouble3 optical, RantDouble2 *pixel);
/* The direction a pixel sees, not of unit length: z is 1 for a pinhole camera. */
RantMathResult i_math_lens_ray(i_MathLens *lens, RantDouble2 pixel, RantDouble3 *optical);

/* A ScalarKind's bytes, 0 for no kind, and one number of it read or written little endian.
 * A write rounds a whole kind to nearest and clamps it, NaN to 0. */
int    i_math_scalar_bytes(RantScalarKind k);
double i_math_scalar_get(RantScalarKind k, const uint8_t *p);
void   i_math_scalar_put(RantScalarKind k, uint8_t *p, double v);

/* Each map after RANT_COLORMAP_GRAY as 256 sRGB steps, from tools/colormaps.py. */
extern const uint8_t i_math_colormaps[5][256][3];

/* A seeded random source: splitmix64 spreads the seed, then xorshift64 star. */
typedef struct { uint64_t s; } i_MathRng;

static inline i_MathRng i_math_rng(uint64_t seed){
    i_MathRng r;
    uint64_t z = seed + 0x9E3779B97F4A7C15ull;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ull;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBull;
    r.s = (z ^ (z >> 31)) | 1u;
    return r;
}

/* In [0, 1). */
static inline double i_math_rng_unit(i_MathRng *r){
    r->s ^= r->s >> 12; r->s ^= r->s << 25; r->s ^= r->s >> 27;
    return (double)((r->s * 0x2545F4914F6CDD1Dull) >> 11) / 9007199254740992.0;
}

/* A 3 by 3 in double, row major, for the work the f32 Matrix3x3 would round. */
typedef struct { double m[3][3]; } i_MathMat3;

i_MathMat3  i_math_mat3_from_quaternion(RantQuaternion q);
RantQuaternion i_math_quaternion_from_mat3(const i_MathMat3 *r);
i_MathMat3  i_math_mat3_multiply(const i_MathMat3 *a, const i_MathMat3 *b);
i_MathMat3  i_math_mat3_transpose(const i_MathMat3 *a);
RantDouble3 i_math_mat3_apply(const i_MathMat3 *a, RantDouble3 v);
/* The symmetric eigen problem of a 3 by 3: values ascending, vectors as columns. */
void        i_math_mat3_eigen(const i_MathMat3 *a, double values[3], i_MathMat3 *vectors);

#endif /* RANT_MATH_INTERNAL_H */


static const RantAxes i_presets[] = {
    { -2,  3,  1,   1.0 },   /* UNITY */
    {  1, -2,  3, 100.0 },   /* UNREAL */
    { -2,  3, -1,   1.0 },   /* GODOT */
    { -2,  3, -1,   1.0 },   /* BEVY */
    {  2,  3,  1,   1.0 },   /* GLTF */
    {  2, -1,  3,   1.0 },   /* BLENDER */
    { -2, -3,  1,   1.0 },   /* OPENCV_CAMERA */
    { -2,  3, -1,   1.0 },   /* OPENGL_CAMERA */
    {  2,  1, -3,   1.0 },   /* NED */
    {  1, -2, -3,   1.0 }    /* FRD */
};

RantAxes rant_axes_of(RantAxesPreset preset){
    int p = (int)preset;
    RantAxes identity = { 1, 2, 3, 1.0 };
    return p >= 0 && p < (int)(sizeof i_presets / sizeof i_presets[0]) ? i_presets[p] : identity;
}

RantMathResult rant_axes_make(int x, int y, int z, double scale, RantAxes *out){
    int ax = x < 0 ? -x : x, ay = y < 0 ? -y : y, az = z < 0 ? -z : z;
    if (!out) return RANT_MATH_ERR_ARGUMENT;
    if (ax < 1 || ax > 3 || ay < 1 || ay > 3 || az < 1 || az > 3) return RANT_MATH_ERR_ARGUMENT;
    if (ax == ay || ax == az || ay == az || !(scale > 0.0)) return RANT_MATH_ERR_ARGUMENT;
    out->x = (int8_t)x; out->y = (int8_t)y; out->z = (int8_t)z; out->scale = scale;
    return RANT_MATH_OK;
}

/* The signed permutation matrix M with tool = M rant, and its determinant, -1 for a tool
 * of the other handedness. A component naming no axis leaves its row zero. */
typedef struct { double m[3][3]; double det; } i_Axes;

static i_Axes i_axes(RantAxes a){
    i_Axes r;
    int code[3], i;
    code[0] = a.x; code[1] = a.y; code[2] = a.z;
    memset(&r, 0, sizeof r);
    for (i = 0; i < 3; i++){
        int c = code[i] < 0 ? -code[i] : code[i];
        if (c >= 1 && c <= 3) r.m[i][c - 1] = code[i] < 0 ? -1.0 : 1.0;
    }
    r.det = r.m[0][0] * (r.m[1][1] * r.m[2][2] - r.m[1][2] * r.m[2][1])
          - r.m[0][1] * (r.m[1][0] * r.m[2][2] - r.m[1][2] * r.m[2][0])
          + r.m[0][2] * (r.m[1][0] * r.m[2][1] - r.m[1][1] * r.m[2][0]);
    return r;
}

static RantDouble3 i_to(const i_Axes *a, RantDouble3 v, double k){
    return rant_double3(k * (a->m[0][0] * v.x + a->m[0][1] * v.y + a->m[0][2] * v.z),
                        k * (a->m[1][0] * v.x + a->m[1][1] * v.y + a->m[1][2] * v.z),
                        k * (a->m[2][0] * v.x + a->m[2][1] * v.y + a->m[2][2] * v.z));
}

static RantDouble3 i_from(const i_Axes *a, RantDouble3 v, double k){
    return rant_double3(k * (a->m[0][0] * v.x + a->m[1][0] * v.y + a->m[2][0] * v.z),
                        k * (a->m[0][1] * v.x + a->m[1][1] * v.y + a->m[2][1] * v.z),
                        k * (a->m[0][2] * v.x + a->m[1][2] * v.y + a->m[2][2] * v.z));
}

static double i_inverse_scale(RantAxes a){ return a.scale > 0.0 ? 1.0 / a.scale : 0.0; }

RantDouble3 rant_axes_point_to(RantAxes axes, RantDouble3 point){
    i_Axes a = i_axes(axes);
    return i_to(&a, point, axes.scale);
}

RantDouble3 rant_axes_point_from(RantAxes axes, RantDouble3 point){
    i_Axes a = i_axes(axes);
    return i_from(&a, point, i_inverse_scale(axes));
}

RantDouble3 rant_axes_direction_to(RantAxes axes, RantDouble3 direction){
    i_Axes a = i_axes(axes);
    return i_to(&a, direction, 1.0);
}

RantDouble3 rant_axes_direction_from(RantAxes axes, RantDouble3 direction){
    i_Axes a = i_axes(axes);
    return i_from(&a, direction, 1.0);
}

/* A quaternion's vector part is a turn axis, so a change of handedness flips it. */
RantQuaternion rant_axes_quaternion_to(RantAxes axes, RantQuaternion q){
    i_Axes a = i_axes(axes);
    RantDouble3 u = i_to(&a, rant_double3(q.x, q.y, q.z), a.det);
    return rant_quaternion(u.x, u.y, u.z, q.w);
}

RantQuaternion rant_axes_quaternion_from(RantAxes axes, RantQuaternion q){
    i_Axes a = i_axes(axes);
    RantDouble3 u = i_from(&a, rant_double3(q.x, q.y, q.z), a.det);
    return rant_quaternion(u.x, u.y, u.z, q.w);
}

RantPose rant_axes_pose_to(RantAxes axes, RantPose p){
    RantPose r;
    r.position = rant_axes_point_to(axes, p.position);
    r.orientation = rant_axes_quaternion_to(axes, p.orientation);
    return r;
}

RantPose rant_axes_pose_from(RantAxes axes, RantPose p){
    RantPose r;
    r.position = rant_axes_point_from(axes, p.position);
    r.orientation = rant_axes_quaternion_from(axes, p.orientation);
    return r;
}

RantTwist rant_axes_twist_to(RantAxes axes, RantTwist t){
    i_Axes a = i_axes(axes);
    RantTwist r;
    r.linear = i_to(&a, t.linear, axes.scale);
    r.angular = i_to(&a, t.angular, a.det);
    return r;
}

RantTwist rant_axes_twist_from(RantAxes axes, RantTwist t){
    i_Axes a = i_axes(axes);
    RantTwist r;
    r.linear = i_from(&a, t.linear, i_inverse_scale(axes));
    r.angular = i_from(&a, t.angular, a.det);
    return r;
}

RantWrench rant_axes_wrench_to(RantAxes axes, RantWrench w){
    i_Axes a = i_axes(axes);
    RantWrench r;
    r.force = i_to(&a, w.force, axes.scale);
    r.torque = i_to(&a, w.torque, a.det * axes.scale * axes.scale);
    return r;
}

RantWrench rant_axes_wrench_from(RantAxes axes, RantWrench w){
    i_Axes a = i_axes(axes);
    double k = i_inverse_scale(axes);
    RantWrench r;
    r.force = i_from(&a, w.force, k);
    r.torque = i_from(&a, w.torque, a.det * k * k);
    return r;
}

RantAccel rant_axes_accel_to(RantAxes axes, RantAccel acc){
    i_Axes a = i_axes(axes);
    RantAccel r;
    r.linear = i_to(&a, acc.linear, axes.scale);
    r.angular = i_to(&a, acc.angular, a.det);
    return r;
}

RantAccel rant_axes_accel_from(RantAxes axes, RantAccel acc){
    i_Axes a = i_axes(axes);
    RantAccel r;
    r.linear = i_from(&a, acc.linear, i_inverse_scale(axes));
    r.angular = i_from(&a, acc.angular, a.det);
    return r;
}

/* C' = J C J^T with J = blockdiag(k M, M). The sign a turn takes cancels in the product. */
static void i_covariance6(const i_Axes *a, int inverse, double k, const RantCovariance6 *in, RantCovariance6 *out){
    double j[6][6], t[6][6], o[6][6];
    int r, c, i;
    memset(j, 0, sizeof j);
    for (r = 0; r < 3; r++)
        for (c = 0; c < 3; c++){
            double m = inverse ? a->m[c][r] : a->m[r][c];
            j[r][c] = k * m;
            j[r + 3][c + 3] = m;
        }
    for (r = 0; r < 6; r++)
        for (c = 0; c < 6; c++){
            double s = 0.0;
            for (i = 0; i < 6; i++) s += j[r][i] * in->m[i][c];
            t[r][c] = s;
        }
    for (r = 0; r < 6; r++)
        for (c = 0; c < 6; c++){
            double s = 0.0;
            for (i = 0; i < 6; i++) s += t[r][i] * j[c][i];
            o[r][c] = s;
        }
    memcpy(out->m, o, sizeof o);
}

void rant_axes_covariance6_to(RantAxes axes, const RantCovariance6 *in, RantCovariance6 *out){
    i_Axes a = i_axes(axes);
    if (in && out) i_covariance6(&a, 0, axes.scale, in, out);
}

void rant_axes_covariance6_from(RantAxes axes, const RantCovariance6 *in, RantCovariance6 *out){
    i_Axes a = i_axes(axes);
    if (in && out) i_covariance6(&a, 1, i_inverse_scale(axes), in, out);
}

void rant_axes_points_to(RantAxes axes, const RantDouble3 *in, RantDouble3 *out, uint32_t count){
    i_Axes a = i_axes(axes);
    uint32_t i;
    if (!in || !out) return;
    for (i = 0; i < count; i++) out[i] = i_to(&a, in[i], axes.scale);
}

void rant_axes_points_from(RantAxes axes, const RantDouble3 *in, RantDouble3 *out, uint32_t count){
    i_Axes a = i_axes(axes);
    double k = i_inverse_scale(axes);
    uint32_t i;
    if (!in || !out) return;
    for (i = 0; i < count; i++) out[i] = i_from(&a, in[i], k);
}

/* base.c */


const char *rant_math_result_text(RantMathResult r){
    switch (r){
    case RANT_MATH_OK:             return "ok";
    case RANT_MATH_ERR_ARGUMENT:   return "a NULL pointer, a count too small, or a value out of range";
    case RANT_MATH_ERR_DEGENERATE: return "no single answer: a singular matrix or points on one line";
    case RANT_MATH_ERR_SPACE:      return "the output is too small";
    case RANT_MATH_ERR_FORMAT:     return "a layout this call cannot read";
    case RANT_MATH_ERR_MEMORY:     return "out of memory";
    case RANT_MATH_ERR_OUTSIDE:    return "a point the call cannot map";
    }
    return "an unknown result";
}

/* camera.c */


static void i_poly_mul(const double *a, int na, const double *b, int nb, double *out){
    int i, j;
    for (i = 0; i <= na + nb; i++) out[i] = 0.0;
    for (i = 0; i <= na; i++) for (j = 0; j <= nb; j++) out[i + j] += a[i] * b[j];
}

/* How far from 0 the polynomial p stays above 0 toward end, end when it holds all the way. No root
 * is closer than a step that keeps each negative term of p's expansion about s under its share of p(s). */
static double i_reach(const double *p, int n, double end){
    double s = 0.0, a[14] = { 0.0 };
    int step, i, k;
    for (step = 0; step < 400; step++){
        double left = end - s, lose = 0.0, h = HUGE_VAL;
        int neg = 0;
        for (i = 0; i <= n; i++) a[i] = p[i];
        for (i = 0; i < n; i++) for (k = n - 1; k >= i; k--) a[k] += s * a[k + 1];
        if (!(a[0] > 0.0)) return s;
        for (k = 1; k <= n; k++) if (a[k] < 0.0) neg++;
        if (!neg) return end;
        if (left < HUGE_VAL){
            for (k = n; k >= 1; k--) lose = lose * left + (a[k] < 0.0 ? -a[k] : 0.0);
            if (lose * left < a[0]) return end;
        }
        for (k = 1; k <= n; k++) if (a[k] < 0.0) h = i_math_min(h, pow(a[0] / (neg * -a[k]), 1.0 / k));
        if (!(h > s * 1e-15)) return s;
        s += h;
    }
    return s;
}

static void i_fold(i_MathLens *L){
    int i;
    L->fold = L->fisheye ? I_MATH_PI : HUGE_VAL;
    for (i = 0; i < L->bounds; i++) L->fold = i_math_min(L->fold, i_reach(L->bound[i], L->degree[i], HUGE_VAL));
}

RantMathResult i_math_lens(const RantCameraIntrinsics *c, int many, i_MathLens *L){
    int i, count;
    if (!c || !(c->fx > 0.0 && c->fy > 0.0) || !i_math_finite(c->fx) || !i_math_finite(c->fy)
        || !i_math_finite(c->cx) || !i_math_finite(c->cy)) return RANT_MATH_ERR_ARGUMENT;
    switch (c->model){
    case RANT_DISTORTION_MODEL_NONE: count = 0; break;
    case RANT_DISTORTION_MODEL_BROWN_CONRADY: count = 5; break;
    case RANT_DISTORTION_MODEL_FISHEYE: count = 4; break;
    case RANT_DISTORTION_MODEL_RATIONAL: count = 8; break;
    default: return RANT_MATH_ERR_ARGUMENT;
    }
    memset(L, 0, sizeof *L);
    L->c = c;
    for (i = 0; i < count; i++){
        if (!i_math_finite(c->coeffs[i])) return RANT_MATH_ERR_ARGUMENT;
        L->k[i] = c->coeffs[i];
    }
    L->fisheye = c->model == RANT_DISTORTION_MODEL_FISHEYE;
    if (L->fisheye){
        /* theta g(theta^2) grows as 1 + 3 k1 theta^2 + 5 k2 theta^4 + 7 k3 theta^6 + 9 k4 theta^8 */
        L->bounds = 1;
        L->bound[0][0] = 1.0;
        for (i = 0; i < 4; i++) L->bound[0][2 * i + 2] = (2 * i + 3) * L->k[i];
        L->degree[0] = 8;
    } else {
        /* The Jacobian is symmetric: radial eigenvalues g = N/M and slope G/M^2, plus a tangential
         * part under t r. While both stay above t r over the whole disk, the map is one to one. */
        double n[4], m[4], dn[3], dm[3], nm[7], a[6], b[6], g[7], mm[7], t = 6.0 * (fabs(L->k[2]) + fabs(L->k[3]));
        n[0] = 1.0; n[1] = L->k[0]; n[2] = L->k[1]; n[3] = L->k[4];
        m[0] = 1.0; m[1] = L->k[5]; m[2] = L->k[6]; m[3] = L->k[7];
        for (i = 0; i < 3; i++){ dn[i] = (i + 1) * n[i + 1]; dm[i] = (i + 1) * m[i + 1]; }
        i_poly_mul(n, 3, m, 3, nm);
        i_poly_mul(dn, 2, m, 3, a);
        i_poly_mul(n, 3, dm, 2, b);
        i_poly_mul(m, 3, m, 3, mm);
        for (i = 0; i <= 6; i++) g[i] = nm[i] + (i ? 2.0 * (a[i - 1] - b[i - 1]) : 0.0);
        /* in r, each power of q lands on an even power and the tangential bound on the odd ones */
        L->bounds = 3;
        for (i = 0; i <= 3; i++){
            L->bound[0][2 * i] = n[i];
            L->bound[0][2 * i + 1] = -t * m[i];
            L->bound[2][2 * i] = m[i];
        }
        for (i = 0; i <= 6; i++){
            L->bound[1][2 * i] = g[i];
            L->bound[1][2 * i + 1] = -t * mm[i];
        }
        L->degree[0] = 7;
        L->degree[1] = 13;
        L->degree[2] = 6;
    }
    for (i = 0; i < L->bounds; i++) while (L->degree[i] > 0 && L->bound[i][L->degree[i]] == 0.0) L->degree[i]--;
    L->fold = -1.0;
    if (many) i_fold(L);
    return RANT_MATH_OK;
}

/* 1 when the lens is one to one on the whole disk out to r, the normalized radius or a fisheye's angle. */
static int i_grows(const i_MathLens *L, double r){
    int i;
    if (L->fisheye && !(r < I_MATH_PI)) return 0;
    if (L->fold >= 0.0) return r < L->fold;
    for (i = 0; i < L->bounds; i++) if (i_reach(L->bound[i], L->degree[i], r) < r) return 0;
    return 1;
}

/* The radius a ray r off the axis lands at, r g(r^2) with r an angle for a fisheye, and its slope. */
static double i_bend(const i_MathLens *L, double r, double *slope){
    const double *k = L->k;
    double q = r * r, g, dg;
    if (L->fisheye){
        g = 1.0 + q * (k[0] + q * (k[1] + q * (k[2] + q * k[3])));
        dg = k[0] + q * (2.0 * k[1] + q * (3.0 * k[2] + q * 4.0 * k[3]));
    } else {
        double n = 1.0 + q * (k[0] + q * (k[1] + q * k[4])), m = 1.0 + q * (k[5] + q * (k[6] + q * k[7]));
        double dn = k[0] + q * (2.0 * k[1] + q * 3.0 * k[4]), dm = k[5] + q * (2.0 * k[6] + q * 3.0 * k[7]);
        g = n / m;
        dg = (dn * m - n * dm) / (m * m);
    }
    if (slope) *slope = g + 2.0 * q * dg;
    return r * g;
}

/* A pinhole lens on the normalized point a, b, and its Jacobian, which is symmetric. */
static void i_distort(const i_MathLens *L, double a, double b, double *xd, double *yd, double j[3]){
    const double *k = L->k;
    double p1 = k[2], p2 = k[3], q = a * a + b * b, dg, g;
    double n = 1.0 + q * (k[0] + q * (k[1] + q * k[4])), m = 1.0 + q * (k[5] + q * (k[6] + q * k[7]));
    double dn = k[0] + q * (2.0 * k[1] + q * 3.0 * k[4]), dm = k[5] + q * (2.0 * k[6] + q * 3.0 * k[7]);
    g = n / m;
    dg = (dn * m - n * dm) / (m * m);
    *xd = a * g + 2.0 * p1 * a * b + p2 * (q + 2.0 * a * a);
    *yd = b * g + p1 * (q + 2.0 * b * b) + 2.0 * p2 * a * b;
    if (j){
        j[0] = g + 2.0 * a * a * dg + 2.0 * p1 * b + 6.0 * p2 * a;
        j[1] = 2.0 * a * b * dg + 2.0 * p1 * a + 2.0 * p2 * b;
        j[2] = g + 2.0 * b * b * dg + 6.0 * p1 * b + 2.0 * p2 * a;
    }
}

RantMathResult i_math_lens_project(i_MathLens *L, RantDouble3 o, RantDouble2 *pixel){
    double xd, yd;
    if (!i_math_finite(o.x) || !i_math_finite(o.y) || !i_math_finite(o.z)) return RANT_MATH_ERR_ARGUMENT;
    if (L->fisheye){
        double r = hypot(o.x, o.y), t = atan2(r, o.z), rd;
        if (!(r > 0.0 || o.z > 0.0) || !i_grows(L, t)) return RANT_MATH_ERR_OUTSIDE;
        rd = i_bend(L, t, NULL);
        xd = r > 0.0 ? rd * o.x / r : 0.0;
        yd = r > 0.0 ? rd * o.y / r : 0.0;
    } else {
        double a, b;
        if (!(o.z > 0.0)) return RANT_MATH_ERR_OUTSIDE;
        a = o.x / o.z;
        b = o.y / o.z;
        /* a lens found one to one everywhere needs no radius */
        if (L->fold != HUGE_VAL && !i_grows(L, hypot(a, b))) return RANT_MATH_ERR_OUTSIDE;
        i_distort(L, a, b, &xd, &yd, NULL);
    }
    pixel->x = L->c->fx * xd + L->c->cx;
    pixel->y = L->c->fy * yd + L->c->cy;
    return RANT_MATH_OK;
}

/* The r on the growing branch that lands at rd, or 0 when the lens reaches no farther. */
static int i_unbend(i_MathLens *L, double rd, double *out){
    double lo = 0.0, hi = rd, r, f, slope, next;
    int i;
    for (i = 0; ; i++){
        if (!i_grows(L, hi)){
            /* the farthest it reaches is at its fold */
            if (L->fold < 0.0) i_fold(L);
            hi = i_math_max(lo, L->fold);
            if (!(i_bend(L, hi, NULL) >= rd)) return 0;
            break;
        }
        if (i_bend(L, hi, NULL) >= rd) break;
        if (i == 200) return 0;
        lo = hi;
        hi *= 2.0;
    }
    /* Newton kept inside the bracket, bisecting when it would leave it */
    r = hi;
    for (i = 0; i < 200; i++){
        f = i_bend(L, r, &slope) - rd;
        if (f == 0.0) break;
        if (f < 0.0) lo = r; else hi = r;
        next = r - f / slope;
        if (!(next > lo && next < hi)) next = 0.5 * (lo + hi);
        if (next == r || hi - lo <= 1e-17 * hi) break;
        r = next;
    }
    *out = r;
    return 1;
}

RantMathResult i_math_lens_ray(i_MathLens *L, RantDouble2 pixel, RantDouble3 *o){
    const RantCameraIntrinsics *c = L->c;
    double xd = (pixel.x - c->cx) / c->fx, yd = (pixel.y - c->cy) / c->fy, rd, r = 0.0, a, b;
    int i, tangential = !L->fisheye && (L->k[2] != 0.0 || L->k[3] != 0.0);
    if (!i_math_finite(xd) || !i_math_finite(yd)) return RANT_MATH_ERR_ARGUMENT;
    if (c->model == RANT_DISTORTION_MODEL_NONE){
        *o = rant_double3(xd, yd, 1.0);
        return RANT_MATH_OK;
    }
    rd = hypot(xd, yd);
    if (rd > 0.0 && !i_unbend(L, rd, &r)){
        /* past the radial reach, the tangential terms may still bring the pixel within the disk */
        if (!tangential) return RANT_MATH_ERR_OUTSIDE;
        if (L->fold < 0.0) i_fold(L);
        if (!(L->fold < HUGE_VAL)) return RANT_MATH_ERR_OUTSIDE;
        r = L->fold * (1.0 - 1e-9);
    }
    if (L->fisheye){
        double s = rd > 0.0 ? sin(r) / rd : 0.0;
        *o = rant_double3(xd * s, yd * s, cos(r));
        return RANT_MATH_OK;
    }
    a = rd > 0.0 ? xd * r / rd : 0.0;
    b = rd > 0.0 ? yd * r / rd : 0.0;
    if (tangential){
        /* the radial answer starts Newton on the tangential terms, each step halved until it gains */
        double ex, ey, e, j[3];
        i_distort(L, a, b, &ex, &ey, j);
        ex -= xd; ey -= yd;
        e = ex * ex + ey * ey;
        for (i = 0; i < 60 && e > 0.0; i++){
            double det = j[0] * j[2] - j[1] * j[1], da, db, t = 1.0, na = a, nb = b, nx = 0.0, ny = 0.0, ne = e, nj[3];
            int h;
            if (!(det > 0.0)) return RANT_MATH_ERR_OUTSIDE;
            da = (j[2] * ex - j[1] * ey) / det;
            db = (j[0] * ey - j[1] * ex) / det;
            for (h = 0; h < 40; h++, t *= 0.5){
                na = a - t * da;
                nb = b - t * db;
                if (!i_grows(L, hypot(na, nb))) continue;
                i_distort(L, na, nb, &nx, &ny, nj);
                nx -= xd; ny -= yd;
                ne = nx * nx + ny * ny;
                if (ne < e) break;
            }
            if (h == 40) break;
            a = na; b = nb; ex = nx; ey = ny; e = ne;
            j[0] = nj[0]; j[1] = nj[1]; j[2] = nj[2];
        }
        if (!(sqrt(e) <= 1e-10 * (1.0 + rd))) return RANT_MATH_ERR_OUTSIDE;
    }
    *o = rant_double3(a, b, 1.0);
    return RANT_MATH_OK;
}

/* A camera's +x ahead, y left and z up from the optical frame's x right, y down and z ahead. */
static RantDouble3 i_body(RantDouble3 o){ return rant_double3(o.z, -o.x, -o.y); }
static RantDouble3 i_optical(RantDouble3 b){ return rant_double3(-b.y, -b.z, b.x); }

RantMathResult rant_camera_project(const RantCameraIntrinsics *camera, RantDouble3 point, RantDouble2 *pixel){
    i_MathLens L;
    RantDouble2 px;
    RantMathResult r;
    if (!pixel) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_lens(camera, 0, &L)) != RANT_MATH_OK) return r;
    if ((r = i_math_lens_project(&L, i_optical(point), &px)) == RANT_MATH_OK) *pixel = px;
    return r;
}

RantMathResult rant_camera_project_points(const RantCameraIntrinsics *camera, const RantDouble3 *points,
                                          RantDouble2 *pixels, uint32_t count){
    i_MathLens L;
    RantMathResult r;
    uint32_t i;
    if (count && (!points || !pixels)) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_lens(camera, 1, &L)) != RANT_MATH_OK) return r;
    for (i = 0; i < count; i++)
        if (i_math_lens_project(&L, i_optical(points[i]), &pixels[i]) != RANT_MATH_OK)
            pixels[i] = rant_double2(NAN, NAN);
    return RANT_MATH_OK;
}

RantMathResult rant_camera_ray(const RantCameraIntrinsics *camera, RantDouble2 pixel, RantRay *out){
    i_MathLens L;
    RantDouble3 o;
    RantMathResult r;
    if (!out) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_lens(camera, 0, &L)) != RANT_MATH_OK) return r;
    if ((r = i_math_lens_ray(&L, pixel, &o)) != RANT_MATH_OK) return r;
    out->origin = rant_double3(0.0, 0.0, 0.0);
    out->direction = rant_double3_normalize(i_body(o));
    return RANT_MATH_OK;
}

RantMathResult rant_camera_unproject(const RantCameraIntrinsics *camera, RantDouble2 pixel, double depth, RantDouble3 *out){
    i_MathLens L;
    RantDouble3 o;
    RantMathResult r;
    if (!out || !(depth > 0.0) || !i_math_finite(depth)) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_lens(camera, 0, &L)) != RANT_MATH_OK) return r;
    if ((r = i_math_lens_ray(&L, pixel, &o)) != RANT_MATH_OK) return r;
    if (!(o.z > 0.0)) return RANT_MATH_ERR_OUTSIDE;
    *out = rant_double3(depth, -o.x * (depth / o.z), -o.y * (depth / o.z));
    return RANT_MATH_OK;
}

RantMathResult rant_camera_scale(const RantCameraIntrinsics *camera, uint32_t width, uint32_t height,
                                 RantCameraIntrinsics *out){
    i_MathLens L;
    RantCameraIntrinsics o;
    double sx, sy;
    if (!out || i_math_lens(camera, 0, &L) != RANT_MATH_OK || !camera->width || !camera->height || !width || !height)
        return RANT_MATH_ERR_ARGUMENT;
    o = *camera;
    sx = (double)width / camera->width;
    sy = (double)height / camera->height;
    o.width = width;
    o.height = height;
    o.fx = camera->fx * sx;
    o.fy = camera->fy * sy;
    /* pixel centers sit at whole numbers, so the image's own edge at -0.5 is what scales */
    o.cx = (camera->cx + 0.5) * sx - 0.5;
    o.cy = (camera->cy + 0.5) * sy - 0.5;
    *out = o;
    return RANT_MATH_OK;
}

RantMathResult rant_camera_crop(const RantCameraIntrinsics *camera, uint32_t x, uint32_t y,
                                uint32_t width, uint32_t height, RantCameraIntrinsics *out){
    i_MathLens L;
    RantCameraIntrinsics o;
    if (!out || i_math_lens(camera, 0, &L) != RANT_MATH_OK || !width || !height
        || (uint64_t)x + width > camera->width || (uint64_t)y + height > camera->height)
        return RANT_MATH_ERR_ARGUMENT;
    o = *camera;
    o.width = width;
    o.height = height;
    o.cx = camera->cx - x;
    o.cy = camera->cy - y;
    *out = o;
    return RANT_MATH_OK;
}

RantMathResult rant_camera_fov(const RantCameraIntrinsics *camera, RantDouble2 *out){
    i_MathLens L;
    RantDouble3 l, r, t, b;
    RantMathResult e;
    if (!out) return RANT_MATH_ERR_ARGUMENT;
    if ((e = i_math_lens(camera, 1, &L)) != RANT_MATH_OK) return e;
    if (!camera->width || !camera->height) return RANT_MATH_ERR_ARGUMENT;
    if ((e = i_math_lens_ray(&L, rant_double2(-0.5, camera->cy), &l)) != RANT_MATH_OK
        || (e = i_math_lens_ray(&L, rant_double2(camera->width - 0.5, camera->cy), &r)) != RANT_MATH_OK
        || (e = i_math_lens_ray(&L, rant_double2(camera->cx, -0.5), &t)) != RANT_MATH_OK
        || (e = i_math_lens_ray(&L, rant_double2(camera->cx, camera->height - 0.5), &b)) != RANT_MATH_OK) return e;
    *out = rant_double2(atan2(r.x, r.z) - atan2(l.x, l.z), atan2(b.y, b.z) - atan2(t.y, t.z));
    return RANT_MATH_OK;
}

RantMathResult rant_camera_from_fov(uint32_t width, uint32_t height, RantDouble2 fov, RantCameraIntrinsics *out){
    RantCameraIntrinsics o;
    if (!out || !width || !height || !(fov.x > 0.0 && fov.x < I_MATH_PI) || !(fov.y >= 0.0 && fov.y < I_MATH_PI))
        return RANT_MATH_ERR_ARGUMENT;
    memset(&o, 0, sizeof o);
    o.width = width;
    o.height = height;
    o.fx = 0.5 * width / tan(0.5 * fov.x);
    o.fy = fov.y > 0.0 ? 0.5 * height / tan(0.5 * fov.y) : o.fx;
    o.cx = 0.5 * (width - 1.0);
    o.cy = 0.5 * (height - 1.0);
    o.model = RANT_DISTORTION_MODEL_NONE;
    *out = o;
    return RANT_MATH_OK;
}

/* cloud.c */


static const RantPointFieldView I_XYZ[] = {
    { "x", 1, 0, RANT_SCALAR_KIND_F32, 1 }, { "y", 1, 4, RANT_SCALAR_KIND_F32, 1 }, { "z", 1, 8, RANT_SCALAR_KIND_F32, 1 },
    { "intensity", 9, 12, RANT_SCALAR_KIND_F32, 1 }
};
static const RantPointFieldView I_RGB[] = {
    { "x", 1, 0, RANT_SCALAR_KIND_F32, 1 }, { "y", 1, 4, RANT_SCALAR_KIND_F32, 1 }, { "z", 1, 8, RANT_SCALAR_KIND_F32, 1 },
    { "rgb", 3, 12, RANT_SCALAR_KIND_F32, 1 }
};
static const RantPointFieldView I_NORMAL[] = {
    { "x", 1, 0, RANT_SCALAR_KIND_F32, 1 }, { "y", 1, 4, RANT_SCALAR_KIND_F32, 1 }, { "z", 1, 8, RANT_SCALAR_KIND_F32, 1 },
    { "normal_x", 8, 12, RANT_SCALAR_KIND_F32, 1 }, { "normal_y", 8, 16, RANT_SCALAR_KIND_F32, 1 },
    { "normal_z", 8, 20, RANT_SCALAR_KIND_F32, 1 }
};

RantPointCloudView rant_point_cloud_layout(RantPointCloudLayout layout){
    RantPointCloudView v;
    memset(&v, 0, sizeof v);
    switch (layout){
    case RANT_POINT_CLOUD_XYZ: v.fields = I_XYZ; v.field_count = 3; break;
    case RANT_POINT_CLOUD_XYZ_INTENSITY: v.fields = I_XYZ; v.field_count = 4; break;
    case RANT_POINT_CLOUD_XYZ_RGB: v.fields = I_RGB; v.field_count = 4; break;
    case RANT_POINT_CLOUD_XYZ_NORMAL: v.fields = I_NORMAL; v.field_count = 6; break;
    default: return v;
    }
    v.point_step = 4 * v.field_count;
    return v;
}

int i_math_scalar_bytes(RantScalarKind k){
    switch (k){
    case RANT_SCALAR_KIND_I8: case RANT_SCALAR_KIND_U8: return 1;
    case RANT_SCALAR_KIND_I16: case RANT_SCALAR_KIND_U16: return 2;
    case RANT_SCALAR_KIND_I32: case RANT_SCALAR_KIND_U32: case RANT_SCALAR_KIND_F32: return 4;
    case RANT_SCALAR_KIND_F64: case RANT_SCALAR_KIND_I64: case RANT_SCALAR_KIND_U64: return 8;
    default: return 0;
    }
}

/* Little endian on any host. */
static uint64_t i_load(const uint8_t *p, int n){
    uint64_t u = 0;
    int i;
    for (i = n - 1; i >= 0; i--) u = u << 8 | p[i];
    return u;
}
static void i_store(uint8_t *p, int n, uint64_t u){
    int i;
    for (i = 0; i < n; i++){ p[i] = (uint8_t)u; u >>= 8; }
}

double i_math_scalar_get(RantScalarKind k, const uint8_t *p){
    uint64_t u = i_load(p, i_math_scalar_bytes(k));
    float f;
    double d;
    switch (k){
    case RANT_SCALAR_KIND_I8: return (int8_t)(uint8_t)u;
    case RANT_SCALAR_KIND_U8: return (double)u;
    case RANT_SCALAR_KIND_I16: return (int16_t)(uint16_t)u;
    case RANT_SCALAR_KIND_U16: return (double)u;
    case RANT_SCALAR_KIND_I32: return (int32_t)(uint32_t)u;
    case RANT_SCALAR_KIND_U32: return (double)u;
    case RANT_SCALAR_KIND_F32: { uint32_t w = (uint32_t)u; memcpy(&f, &w, sizeof f); return f; }
    case RANT_SCALAR_KIND_F64: memcpy(&d, &u, sizeof d); return d;
    case RANT_SCALAR_KIND_I64: return (double)(int64_t)u;
    case RANT_SCALAR_KIND_U64: return (double)u;
    default: return 0.0;
    }
}

/* Nearest, halves away from 0, held to lo and hi, which a double holds exactly. */
static double i_whole(double v, double lo, double hi){
    if (!(v == v)) return 0.0;
    v = v < 0.0 ? -floor(0.5 - v) : floor(v + 0.5);
    return v < lo ? lo : (v > hi ? hi : v);
}

void i_math_scalar_put(RantScalarKind k, uint8_t *p, double v){
    float f;
    uint32_t w;
    uint64_t u;
    switch (k){
    case RANT_SCALAR_KIND_I8: p[0] = (uint8_t)(int8_t)i_whole(v, -128.0, 127.0); return;
    case RANT_SCALAR_KIND_U8: p[0] = (uint8_t)i_whole(v, 0.0, 255.0); return;
    case RANT_SCALAR_KIND_I16: i_store(p, 2, (uint16_t)(int16_t)i_whole(v, -32768.0, 32767.0)); return;
    case RANT_SCALAR_KIND_U16: i_store(p, 2, (uint16_t)i_whole(v, 0.0, 65535.0)); return;
    case RANT_SCALAR_KIND_I32: i_store(p, 4, (uint32_t)(int32_t)i_whole(v, -2147483648.0, 2147483647.0)); return;
    case RANT_SCALAR_KIND_U32: i_store(p, 4, (uint32_t)i_whole(v, 0.0, 4294967295.0)); return;
    case RANT_SCALAR_KIND_F32: f = (float)v; memcpy(&w, &f, sizeof w); i_store(p, 4, w); return;
    case RANT_SCALAR_KIND_F64: memcpy(&u, &v, sizeof u); i_store(p, 8, u); return;
    /* 2^63 and 2^64 are past the top, so they stand for it */
    case RANT_SCALAR_KIND_I64:
        v = i_whole(v, -9223372036854775808.0, 9223372036854775808.0);
        i_store(p, 8, v >= 9223372036854775808.0 ? (uint64_t)INT64_MAX : (uint64_t)(int64_t)v);
        return;
    case RANT_SCALAR_KIND_U64:
        v = i_whole(v, 0.0, 18446744073709551616.0);
        i_store(p, 8, v >= 18446744073709551616.0 ? UINT64_MAX : (uint64_t)v);
        return;
    default: return;
    }
}

/* What every view must pass, and how many points it holds. */
static RantMathResult i_cloud(const RantPointCloudView *c, uint32_t *n){
    uint32_t i;
    if (!c) return RANT_MATH_ERR_ARGUMENT;
    if (!c->point_step || (c->size && !c->data) || (c->field_count && !c->fields)) return RANT_MATH_ERR_FORMAT;
    if (c->size % c->point_step || c->size / c->point_step > UINT32_MAX) return RANT_MATH_ERR_FORMAT;
    for (i = 0; i < c->field_count; i++){
        const RantPointFieldView *f = &c->fields[i];
        int b = i_math_scalar_bytes(f->kind);
        if (!b || !f->count || (f->name_len && !f->name)) return RANT_MATH_ERR_FORMAT;
        if ((uint64_t)f->offset + (uint64_t)b * f->count > c->point_step) return RANT_MATH_ERR_FORMAT;
    }
    *n = (uint32_t)(c->size / c->point_step);
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_check(const RantPointCloudView *cloud){
    uint32_t n;
    return i_cloud(cloud, &n);
}

/* After i_cloud has passed. */
static const RantPointFieldView *i_field(const RantPointCloudView *c, const char *name){
    size_t len;
    uint32_t i;
    if (!name) return NULL;
    len = strlen(name);
    for (i = 0; i < c->field_count; i++)
        if (c->fields[i].name_len == len && (!len || memcmp(c->fields[i].name, name, len) == 0)) return &c->fields[i];
    return NULL;
}

const RantPointFieldView *rant_point_cloud_field(const RantPointCloudView *cloud, const char *name){
    uint32_t n;
    return i_cloud(cloud, &n) == RANT_MATH_OK ? i_field(cloud, name) : NULL;
}

/* A view checked, with its x, y and z, and the room rule applied to count when it is not NULL. */
static RantMathResult i_xyz(const RantPointCloudView *c, const RantPointFieldView **xyz, uint32_t *n){
    RantMathResult r = i_cloud(c, n);
    if (r != RANT_MATH_OK) return r;
    xyz[0] = i_field(c, "x");
    xyz[1] = i_field(c, "y");
    xyz[2] = i_field(c, "z");
    return xyz[0] && xyz[1] && xyz[2] ? RANT_MATH_OK : RANT_MATH_ERR_FORMAT;
}

static RantDouble3 i_point(const uint8_t *p, const RantPointFieldView **xyz){
    return rant_double3(i_math_scalar_get(xyz[0]->kind, p + xyz[0]->offset),
                        i_math_scalar_get(xyz[1]->kind, p + xyz[1]->offset),
                        i_math_scalar_get(xyz[2]->kind, p + xyz[2]->offset));
}
static void i_set_point(uint8_t *p, const RantPointFieldView **xyz, RantDouble3 v){
    i_math_scalar_put(xyz[0]->kind, p + xyz[0]->offset, v.x);
    i_math_scalar_put(xyz[1]->kind, p + xyz[1]->offset, v.y);
    i_math_scalar_put(xyz[2]->kind, p + xyz[2]->offset, v.z);
}

RantMathResult rant_point_cloud_read_points(const RantPointCloudView *cloud, RantDouble3 *out, uint32_t *count){
    const RantPointFieldView *xyz[3];
    uint32_t n, i;
    RantMathResult r;
    if (!count) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_xyz(cloud, xyz, &n)) != RANT_MATH_OK) return r;
    if ((r = i_math_room(count, n, out)) != RANT_MATH_OK) return r;
    for (i = 0; i < n; i++) out[i] = i_point(cloud->data + (size_t)i * cloud->point_step, xyz);
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_write_points(RantPointCloudView *cloud, const RantDouble3 *points, uint32_t count){
    const RantPointFieldView *xyz[3];
    uint32_t n, i;
    RantMathResult r;
    if ((r = i_xyz(cloud, xyz, &n)) != RANT_MATH_OK) return r;
    if (count != n || (n && !points)) return RANT_MATH_ERR_ARGUMENT;
    for (i = 0; i < n; i++) i_set_point(cloud->data + (size_t)i * cloud->point_step, xyz, points[i]);
    return RANT_MATH_OK;
}

static RantMathResult i_named(const RantPointCloudView *c, const char *name, const RantPointFieldView **f, uint32_t *n){
    RantMathResult r;
    if (!name) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_cloud(c, n)) != RANT_MATH_OK) return r;
    *f = i_field(c, name);
    return *f ? RANT_MATH_OK : RANT_MATH_ERR_FORMAT;
}

RantMathResult rant_point_cloud_read_values(const RantPointCloudView *cloud, const char *field, double *out, uint32_t *count){
    const RantPointFieldView *f;
    uint32_t n, i, j, b;
    RantMathResult r;
    if (!count) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_named(cloud, field, &f, &n)) != RANT_MATH_OK) return r;
    if ((uint64_t)n * f->count > UINT32_MAX) return RANT_MATH_ERR_FORMAT;
    if ((r = i_math_room(count, n * f->count, out)) != RANT_MATH_OK) return r;
    b = (uint32_t)i_math_scalar_bytes(f->kind);
    for (i = 0; i < n; i++){
        const uint8_t *p = cloud->data + (size_t)i * cloud->point_step + f->offset;
        for (j = 0; j < f->count; j++) *out++ = i_math_scalar_get(f->kind, p + j * b);
    }
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_write_values(RantPointCloudView *cloud, const char *field, const double *values,
                                             uint32_t count){
    const RantPointFieldView *f;
    uint32_t n, i, j, b;
    RantMathResult r;
    if ((r = i_named(cloud, field, &f, &n)) != RANT_MATH_OK) return r;
    if ((uint64_t)n * f->count != count || (count && !values)) return RANT_MATH_ERR_ARGUMENT;
    b = (uint32_t)i_math_scalar_bytes(f->kind);
    for (i = 0; i < n; i++){
        uint8_t *p = cloud->data + (size_t)i * cloud->point_step + f->offset;
        for (j = 0; j < f->count; j++) i_math_scalar_put(f->kind, p + j * b, *values++);
    }
    return RANT_MATH_OK;
}

/* The packed colour field, 4 bytes blue, green, red and alpha, and whether it holds alpha. */
static RantMathResult i_packed(const RantPointCloudView *c, const RantPointFieldView **f, int *alpha, uint32_t *n){
    RantMathResult r = i_cloud(c, n);
    if (r != RANT_MATH_OK) return r;
    *alpha = 1;
    if (!(*f = i_field(c, "rgba"))){ *alpha = 0; *f = i_field(c, "rgb"); }
    return *f && i_math_scalar_bytes((*f)->kind) == 4 ? RANT_MATH_OK : RANT_MATH_ERR_FORMAT;
}

RantMathResult rant_point_cloud_read_colors(const RantPointCloudView *cloud, RantColor *out, uint32_t *count){
    const RantPointFieldView *f;
    uint32_t n, i;
    int alpha;
    RantMathResult r;
    if (!count) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_packed(cloud, &f, &alpha, &n)) != RANT_MATH_OK) return r;
    if ((r = i_math_room(count, n, out)) != RANT_MATH_OK) return r;
    for (i = 0; i < n; i++){
        const uint8_t *p = cloud->data + (size_t)i * cloud->point_step + f->offset;
        out[i] = rant_color(p[2], p[1], p[0], alpha ? p[3] : 255);
    }
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_write_colors(RantPointCloudView *cloud, const RantColor *colors, uint32_t count){
    const RantPointFieldView *f;
    uint32_t n, i;
    int alpha;
    RantMathResult r;
    if ((r = i_packed(cloud, &f, &alpha, &n)) != RANT_MATH_OK) return r;
    if (count != n || (n && !colors)) return RANT_MATH_ERR_ARGUMENT;
    for (i = 0; i < n; i++){
        uint8_t *p = cloud->data + (size_t)i * cloud->point_step + f->offset;
        p[0] = colors[i].b; p[1] = colors[i].g; p[2] = colors[i].r; p[3] = alpha ? colors[i].a : 255;
    }
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_transform(RantPointCloudView *cloud, RantPose pose){
    const RantPointFieldView *xyz[3], *nxyz[3];
    i_MathMat3 m;
    uint32_t n, i;
    int normals;
    RantMathResult r;
    if ((r = i_xyz(cloud, xyz, &n)) != RANT_MATH_OK) return r;
    nxyz[0] = i_field(cloud, "normal_x");
    nxyz[1] = i_field(cloud, "normal_y");
    nxyz[2] = i_field(cloud, "normal_z");
    normals = nxyz[0] && nxyz[1] && nxyz[2];
    m = i_math_mat3_from_quaternion(pose.orientation);
    for (i = 0; i < n; i++){
        uint8_t *p = cloud->data + (size_t)i * cloud->point_step;
        i_set_point(p, xyz, rant_double3_add(pose.position, i_math_mat3_apply(&m, i_point(p, xyz))));
        if (normals) i_set_point(p, nxyz, i_math_mat3_apply(&m, i_point(p, nxyz)));
    }
    return RANT_MATH_OK;
}

RantMathResult rant_point_cloud_select(const RantPointCloudView *cloud, const uint8_t *keep, uint8_t *data, uint32_t *count){
    uint32_t n, i, need = 0, k = 0;
    RantMathResult r;
    if (!count || !keep) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_cloud(cloud, &n)) != RANT_MATH_OK) return r;
    for (i = 0; i < n; i++) need += keep[i] != 0;
    if ((r = i_math_room(count, need, data)) != RANT_MATH_OK) return r;
    /* each point lands at or before its own place, so data may be the cloud's own */
    for (i = 0; i < n; i++)
        if (keep[i]) memmove(data + (size_t)k++ * cloud->point_step, cloud->data + (size_t)i * cloud->point_step,
                             cloud->point_step);
    return RANT_MATH_OK;
}

RantMathResult rant_laser_scan_points(const RantLaserScanView *scan, RantDouble2 *out, uint32_t *count){
    uint32_t i, e;
    RantMathResult r;
    if (!scan || !count || (scan->range_count && !scan->ranges)) return RANT_MATH_ERR_ARGUMENT;
    if (!i_math_finite(scan->angle_min) || !i_math_finite(scan->angle_step)) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_room(count, scan->range_count, out)) != RANT_MATH_OK) return r;
    e = scan->echoes ? scan->echoes : 1;
    for (i = 0; i < scan->range_count; i++){
        double d = scan->ranges[i], a = scan->angle_min + (double)(i / e) * scan->angle_step;
        if (i_math_finite(d) && d >= scan->range_min && d <= scan->range_max) out[i] = rant_double2(d * cos(a), d * sin(a));
        else out[i] = rant_double2(NAN, NAN);
    }
    return RANT_MATH_OK;
}

RantMathResult rant_image_depth_points(const RantImageView *depth, const RantCameraIntrinsics *camera, RantDouble3 *out,
                                       uint32_t *count){
    i_MathLens L;
    RantMathResult r;
    uint32_t x, y;
    size_t stride;
    int wide;
    if (!count || !camera) return RANT_MATH_ERR_ARGUMENT;
    if ((r = rant_image_check(depth)) != RANT_MATH_OK) return r;
    if (depth->format != RANT_IMAGE_FORMAT_MONO16 && depth->format != RANT_IMAGE_FORMAT_MONOF32) return RANT_MATH_ERR_FORMAT;
    if (depth->width != camera->width || depth->height != camera->height) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_lens(camera, 1, &L)) != RANT_MATH_OK) return r;
    if ((uint64_t)depth->width * depth->height > UINT32_MAX) return RANT_MATH_ERR_ARGUMENT;
    if ((r = i_math_room(count, depth->width * depth->height, out)) != RANT_MATH_OK) return r;
    wide = depth->format == RANT_IMAGE_FORMAT_MONOF32;
    stride = depth->stride ? depth->stride : (size_t)depth->width * (wide ? 4 : 2);
    for (y = 0; y < depth->height; y++){
        const uint8_t *row = depth->data + y * stride;
        for (x = 0; x < depth->width; x++){
            double d = wide ? i_math_scalar_get(RANT_SCALAR_KIND_F32, row + 4 * x)
                            : 0.001 * i_math_scalar_get(RANT_SCALAR_KIND_U16, row + 2 * x);
            RantDouble3 o;
            if (d > 0.0 && i_math_finite(d) && i_math_lens_ray(&L, rant_double2(x, y), &o) == RANT_MATH_OK && o.z > 0.0)
                *out++ = rant_double3(d, -o.x * (d / o.z), -o.y * (d / o.z));
            else
                *out++ = rant_double3(NAN, NAN, NAN);
        }
    }
    return RANT_MATH_OK;
}

/* color.c */


/* 0 to 1 as a byte the way the HMI writes one, with NaN as 0. */
static uint8_t i_byte(double v){
    if (!(v > 0.0)) return 0;
    if (v >= 1.0) return 255;
    return (uint8_t)floor(v * 255.0 + 0.5);
}

static double i_linear(double v){ return v <= 0.04045 ? v / 12.92 : pow((v + 0.055) / 1.055, 2.4); }
static double i_gamma(double v){ return v <= 0.0031308 ? 12.92 * i_math_max(v, 0.0) : 1.055 * pow(v, 1.0 / 2.4) - 0.055; }

/* Ottosson's OKLab with the HMI's constants, so both mix to the same bytes. */
typedef struct { double l, a, b, alpha; } i_Lab;

static i_Lab i_lab(RantColor c){
    double r = i_linear(c.r / 255.0), g = i_linear(c.g / 255.0), b = i_linear(c.b / 255.0);
    double l = cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
    double m = cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
    double s = cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
    i_Lab o;
    o.l = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
    o.a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
    o.b = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
    o.alpha = c.a / 255.0;
    return o;
}

static RantColor i_srgb(i_Lab c){
    double l = c.l + 0.3963377774 * c.a + 0.2158037573 * c.b;
    double m = c.l - 0.1055613458 * c.a - 0.0638541728 * c.b;
    double s = c.l - 0.0894841775 * c.a - 1.291485548 * c.b;
    l = l * l * l; m = m * m * m; s = s * s * s;
    return rant_color(i_byte(i_gamma(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s)),
                      i_byte(i_gamma(-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s)),
                      i_byte(i_gamma(-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s)),
                      i_byte(c.alpha));
}

RantColor rant_color_mix(RantColor a, RantColor b, double t){
    i_Lab p = i_lab(a), q = i_lab(b), o;
    o.l = p.l + (q.l - p.l) * t;
    o.a = p.a + (q.a - p.a) * t;
    o.b = p.b + (q.b - p.b) * t;
    o.alpha = p.alpha + (q.alpha - p.alpha) * t;
    return i_srgb(o);
}

RantFloat4 rant_color_to_linear(RantColor c){
    return rant_float4((float)i_linear(c.r / 255.0), (float)i_linear(c.g / 255.0),
                       (float)i_linear(c.b / 255.0), (float)(c.a / 255.0));
}

RantColor rant_color_from_linear(RantFloat4 v){
    return rant_color(i_byte(i_gamma(v.x)), i_byte(i_gamma(v.y)), i_byte(i_gamma(v.z)), i_byte(v.w));
}

RantColor rant_colormap_at(RantColormap map, double t){
    const uint8_t *p;
    int i;
    if (t != t || (int)map < 0 || (int)map > (int)RANT_COLORMAP_TURBO) return rant_color(0, 0, 0, 0);
    /* matplotlib's rule: step floor(256 t), with t = 1 the last step */
    i = t <= 0.0 ? 0 : (t >= 1.0 ? 255 : (int)(t * 256.0));
    if (i > 255) i = 255;
    if (map == RANT_COLORMAP_GRAY) return rant_color((uint8_t)i, (uint8_t)i, (uint8_t)i, 255);
    p = i_math_colormaps[(int)map - 1][i];
    return rant_color(p[0], p[1], p[2], 255);
}

